CustomField.formula:
if ( ispickval(Depreciation_Method__c, "Straight Line 10"), IF(
  AND(
    MONTH( Date_in_Service__c ) = 2,
    DAY( Date_in_Service__c ) = 29,
    NOT( 
      OR( 
        MOD( YEAR( Date_in_Service__c ), 400 ) = 0, 
        AND( 
          MOD( YEAR( Date_in_Service__c ), 4 ) = 0,
          MOD( YEAR( Date_in_Service__c ), 100 ) != 0
        )
      )
    ) 
  ),
  DATE( YEAR( Date_in_Service__c ) + 10, 3, 1),
  DATE( YEAR( Date_in_Service__c ) + 10, MONTH( Date_in_Service__c ), DAY( Date_in_Service__c ) )
),

if ( ispickval(Depreciation_Method__c, "Straight Line 5"), IF(
  AND(
    MONTH( Date_in_Service__c ) = 2,
    DAY( Date_in_Service__c ) = 29,
    NOT( 
      OR( 
        MOD( YEAR( Date_in_Service__c ), 400 ) = 0, 
        AND( 
          MOD( YEAR( Date_in_Service__c ), 4 ) = 0,
          MOD( YEAR( Date_in_Service__c ), 100 ) != 0
        )
      )
    ) 
  ),
  DATE( YEAR( Date_in_Service__c ) + 5, 3, 1),
  DATE( YEAR( Date_in_Service__c ) + 5, MONTH( Date_in_Service__c ), DAY( Date_in_Service__c ) )
),

if ( ispickval(Depreciation_Method__c, "Straight Line 3"), IF(
  AND(
    MONTH( Date_in_Service__c ) = 2,
    DAY( Date_in_Service__c ) = 29,
    NOT( 
      OR( 
        MOD( YEAR( Date_in_Service__c ), 400 ) = 0, 
        AND( 
          MOD( YEAR( Date_in_Service__c ), 4 ) = 0,
          MOD( YEAR( Date_in_Service__c ), 100 ) != 0
        )
      )
    ) 
  ),
  DATE( YEAR( Date_in_Service__c ) + 3, 3, 1),
  DATE( YEAR( Date_in_Service__c ) + 3, MONTH( Date_in_Service__c ), DAY( Date_in_Service__c ) )
),

NULL)))
